<?php
/**
 * deploy_all_8.php - Apollo Seikotsuin Lightweight & UTF-8 Deployment Script
 * Encoding: UTF-8 (No BOM)
 * Brand: Orange & Yellow
 */

// Force UTF-8 HTTP response header to eliminate character encoding issues
header('Content-Type: text/html; charset=UTF-8');
if (function_exists('mb_internal_encoding')) {
    mb_language('Japanese');
    mb_internal_encoding('UTF-8');
}

error_reporting(E_ALL & ~E_WARNING);
ini_set('display_errors', 1);

$targetDir = __DIR__;
$files = [
    'index.html' => '',
    'menu.html' => '',
    'staff.html' => '',
    'photo.html' => '',
    'gallery.html' => '',
    'blog.html' => '',
    'review.html' => '',
    'access.html' => '',
    'map.html' => '',
    'accident.html' => '',
    'coupon.html' => '',
    'theme.css' => '',
    '.htaccess' => 'IyBGb3JjZSBVVEYtOCBFbmNvZGluZyBmb3IgUGxlc2sgQXBhY2hlL05naW54CkFkZERlZmF1bHRDaGFyc2V0IFVURi04CkFkZENoYXJzZXQgVVRGLTggLmh0bWwgLmNzcyAuanMgLmpzb24gLnBocAoKPElmTW9kdWxlIG1vZF9oZWFkZXJzLmM+CiAgICBIZWFkZXIgc2V0IENvbnRlbnQtVHlwZSAidGV4dC9odG1sOyBjaGFyc2V0PVVURi04Igo8L0lmTW9kdWxlPgo=',
];

echo "<!DOCTYPE html><html lang='ja'><head><meta charset='UTF-8'><title>Apollo Seikotsuin Deployment</title></head><body>";
echo "<h1 style='color: #F39800;'>Deployment: Apollo Seikotsuin</h1>";
echo "<ul>";

foreach ($files as $filename => $base64Content) {
    $targetPath = $targetDir . '/' . $filename;
    $dir = dirname($targetPath);
    
    if (!is_dir($dir)) {
        @mkdir($dir, 0777, true);
    }
    @chmod($dir, 0777);

    if (file_exists($targetPath)) {
        @chmod($targetPath, 0666);
    }
    
    // Backup existing HTML/CSS if in root
    if (file_exists($targetPath) && strpos($filename, '/') === false) {
        $backupPath = $targetDir . '/backup_' . $filename . '_' . date('Ymd_His');
        if (@copy($targetPath, $backupPath)) {
            @chmod($backupPath, 0666);
        }
    }
    
    $decodedData = base64_decode($base64Content);
    
    $writeSuccess = @file_put_contents($targetPath, $decodedData);
    if ($writeSuccess === false && file_exists($targetPath)) {
        @unlink($targetPath);
        $writeSuccess = @file_put_contents($targetPath, $decodedData);
    }
    
    if ($writeSuccess !== false) {
        @chmod($targetPath, 0666);
        echo "<li>✅ Updated: <strong>$filename</strong></li>";
    } else {
        echo "<li>⚠️ Skipped / Error: <strong>$filename</strong></li>";
    }
}

// Cleanup legacy files if present
if (file_exists($targetDir . '/admin.html')) {
    @chmod($targetDir . '/admin.html', 0666);
    @unlink($targetDir . '/admin.html');
    echo "<li>⚠️ Deleted legacy admin.html</li>";
}
if (file_exists($targetDir . '/index.php')) {
    @chmod($targetDir . '/index.php', 0666);
    @unlink($targetDir . '/index.php');
    echo "<li>⚠️ Deleted index.php</li>";
}

echo "</ul>";
echo "<p style='color: green; font-weight: bold;'>Success! All 8 pages, theme.css, and .htaccess have been deployed in UTF-8.</p>";
echo '<p><a href="index.html" style="font-size: 20px; font-weight: bold; color: #F39800;">サイトを確認する</a></p>';
echo "</body></html>";
?>